Extensions.ExtractScript:
param([xml] $Document, [string] $Pass)
$utf8bom = [System.Text.UTF8Encoding]::new($true)
foreach ($file in $Document.GetElementsByTagName('File')) {
    if ($file.GetAttribute('pass') -ne $Pass) { continue }
    $path = [System.Environment]::ExpandEnvironmentVariables($file.GetAttribute('path'))
    New-Item -ItemType Directory -Path (Split-Path -Parent $path) -Force -ErrorAction SilentlyContinue | Out-Null
    [System.IO.File]::WriteAllText($path, $file.InnerText.Trim(), $utf8bom)
}

Extensions.File:
# Roda no WinPE, antes de qualquer coisa ser gravada. # Procura o disco alvo pelo serial ou pelo modelo. Só particiona se achar EXATAMENTE um; senão aborta # e o Setup para com erro, sem ter apagado nada. Pendrives nunca são candidatos.
$Serial = 'AA09B5211012T9' # Get-Disk | Select-Object FriendlyName, SerialNumber $Modelo = 'MP700 ELITE'
$log = 'X:\mywiniso\disco.log' function Log($m) { Write-Output $m; Add-Content -Path $log -Value $m }
$discos = @(Get-CimInstance -ClassName Win32_DiskDrive) Log "Discos vistos pelo WinPE:" foreach ($d in $discos) { Log (" [{0}] {1} | serial={2} | {3} GB | {4}" -f $d.Index, $d.Model, $d.SerialNumber, [math]::Round($d.Size / 1GB), $d.InterfaceType) }
$alvo = @($discos | Where-Object { $serialLimpo = ($_.SerialNumber -replace '[^A-Za-z0-9]', '') ($serialLimpo -like "*$Serial*" -or $_.Model -like "*$Modelo*") -and $_.InterfaceType -ne 'USB' -and $_.PNPDeviceID -notlike 'USBSTOR*' })
if ($alvo.Count -ne 1) { Log "ERRO: esperava 1 disco com serial '$Serial' ou modelo '$Modelo', achei $($alvo.Count). Nada foi apagado." Start-Process notepad.exe -ArgumentList $log -Wait exit 1 }
$n = $alvo[0].Index Log "Alvo: disco $n ($($alvo[0].Model)). Apagando e particionando (GPT: EFI 300 MB, MSR 16 MB, Windows, Recovery 1 GB)."
$script = @" select disk $n clean convert gpt create partition efi size=300 format quick fs=fat32 label="System" create partition msr size=16 create partition primary shrink minimum=1024 format quick fs=ntfs label="Windows" create partition primary format quick fs=ntfs label="Recovery" set id="de94bba4-06d1-4d40-a16a-bfd50179d6ac" gpt attributes=0x8000000000000001 list partition "@ $script | Set-Content -Path 'X:\mywiniso\diskpart.txt' -Encoding ASCII $saida = diskpart.exe /s 'X:\mywiniso\diskpart.txt' 2>&1 $saida | ForEach-Object { Log ([string]$_) } if ($LASTEXITCODE -ne 0) { Log "ERRO: diskpart saiu com código $LASTEXITCODE." Start-Process notepad.exe -ArgumentList $log -Wait exit $LASTEXITCODE } Log "Disco pronto." exit 0

# Roda no passo "specialize", como SYSTEM, antes do primeiro boot na área de trabalho. # Só coisas de sistema. Preferências de usuário (tema, barra, mouse) ficam no setup.ps1 do repositório.
$ErrorActionPreference = 'Continue' Start-Transcript -Path 'C:\Windows\Setup\Scripts\especializar.log' -Force | Out-Null
function Set-Reg([string] $Path, [string] $Name, $Value, [string] $Type = 'DWord') { if (-not (Test-Path -LiteralPath $Path)) { New-Item -Path $Path -Force | Out-Null } Set-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -Type $Type -Force }
# --- Bloatware (pacotes provisionados: nunca chegam a ser instalados para o usuário) --- # Ficam: Loja e App Installer (o winget depende deles), Calculadora, Fotos, Bloco de Notas, Paint, # Ferramenta de Captura, Terminal, Xbox Identity Provider (login em jogos da Loja). $bloat = @( 'Clipchamp.Clipchamp', 'Microsoft.549981C3F5F10', 'Microsoft.BingNews', 'Microsoft.BingSearch', 'Microsoft.BingWeather', 'Microsoft.Copilot', 'Microsoft.Edge.GameAssist', 'Microsoft.GamingApp', 'Microsoft.GetHelp', 'Microsoft.Getstarted', 'Microsoft.MicrosoftOfficeHub', 'Microsoft.MicrosoftSolitaireCollection', 'Microsoft.MicrosoftStickyNotes', 'Microsoft.OutlookForWindows', 'Microsoft.People', 'Microsoft.PowerAutomateDesktop', 'Microsoft.Todos', 'Microsoft.Windows.DevHome', 'Microsoft.WindowsAlarms', 'Microsoft.WindowsCamera', 'Microsoft.WindowsFeedbackHub', 'Microsoft.WindowsMaps', 'Microsoft.WindowsSoundRecorder', 'Microsoft.Xbox.TCUI', 'Microsoft.XboxGamingOverlay', 'Microsoft.XboxSpeechToTextOverlay', 'Microsoft.YourPhone', 'Microsoft.ZuneMusic', 'Microsoft.ZuneVideo', 'MicrosoftCorporationII.MicrosoftFamily', 'MicrosoftCorporationII.QuickAssist', 'MSTeams', 'microsoft.windowscommunicationsapps' ) Get-AppxProvisionedPackage -Online | Where-Object { $bloat -contains $_.DisplayName } | ForEach-Object { Write-Output "removendo $($_.DisplayName)" Remove-AppxProvisionedPackage -Online -PackageName $_.PackageName | Out-Null }
# Outlook e Dev Home ficam agendados para instalar depois do OOBE; tirar o agendamento. foreach ($k in 'OutlookUpdate', 'DevHomeUpdate') { Remove-Item -LiteralPath "HKLM:\SOFTWARE\Microsoft\WindowsUpdate\Orchestrator\UScheduler_Oobe\$k" -Force -ErrorAction SilentlyContinue }
# Recall (só existe em Copilot+ PC; inofensivo aqui) Disable-WindowsOptionalFeature -Online -FeatureName 'Recall' -NoRestart -ErrorAction SilentlyContinue | Out-Null
# --- OneDrive: desinstala e tira do autostart do perfil padrão --- foreach ($exe in "$env:SystemRoot\System32\OneDriveSetup.exe", "$env:SystemRoot\SysWOW64\OneDriveSetup.exe") { if (Test-Path -LiteralPath $exe) { Start-Process -FilePath $exe -ArgumentList '/uninstall' -Wait } } reg.exe load HKU\DefaultUser C:\Users\Default\NTUSER.DAT | Out-Null reg.exe delete "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Run" /v OneDriveSetup /f 2>$null reg.exe unload HKU\DefaultUser | Out-Null
# --- Políticas: telemetria, sugestões, Copilot, widgets, anúncios, Edge --- Set-Reg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\OOBE' 'BypassNRO' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection' 'AllowTelemetry' 0 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' 'DisableWindowsConsumerFeatures' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' 'DisableCloudOptimizedContent' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot' 'TurnOffWindowsCopilot' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Dsh' 'AllowNewsAndInterests' 0 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AdvertisingInfo' 'DisabledByGroupPolicy' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'HideFirstRunExperience' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU' 'NoAutoRebootWithLoggedOnUsers' 1
# --- Sistema --- Set-Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' 'HiberbootEnabled' 0 # inicialização rápida desligada Set-Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' 'LongPathsEnabled' 1
# Plano de energia "Alto desempenho" $alto = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c' powercfg.exe /setactive $alto 2>$null if ($LASTEXITCODE -ne 0) { $saida = powercfg.exe /duplicatescheme $alto if ($saida -match '([0-9a-f-]{36})') { powercfg.exe /setactive $Matches[1] } }
Stop-Transcript | Out-Null exit 0
